import { readFileSync } from 'fs';

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

const filePath = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_3u8jixpn/graph.json';
const data = readFileSync(filePath, 'utf-8');
const graph: Graph = JSON.parse(data);

// Build adjacency list (undirected)
const adj = new Map<string, { to: string; weight: number }[]>();
for (const node of graph.nodes) {
  adj.set(node, []);
}
for (const edge of graph.edges) {
  adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
  adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
}

// Dijkstra's algorithm from node "A"
const dist = new Map<string, number>();
const visited = new Set<string>();

for (const node of graph.nodes) {
  dist.set(node, Infinity);
}
dist.set('A', 0);

for (let i = 0; i < graph.nodes.length; i++) {
  let minNode: string | null = null;
  let minDist = Infinity;
  for (const node of graph.nodes) {
    if (!visited.has(node) && dist.get(node)! < minDist) {
      minDist = dist.get(node)!;
      minNode = node;
    }
  }
  if (minNode === null) break;
  visited.add(minNode);

  const neighbors = adj.get(minNode)!;
  for (const { to, weight } of neighbors) {
    if (!visited.has(to)) {
      const newDist = dist.get(minNode)! + weight;
      if (newDist < dist.get(to)!) {
        dist.set(to, newDist);
      }
    }
  }
}

// Output
const sorted = [...graph.nodes].sort();
const lines: string[] = [];
lines.push('=== Shortest Paths from A ===');
lines.push('');
for (const node of sorted) {
  lines.push(`A -> ${node}: ${dist.get(node)}`);
}
process.stdout.write(lines.join('\n') + '\n');

