import * as fs from 'fs';

type Json = string | number | boolean | null | Json[] | { [key: string]: Json };

function isObject(val: Json): val is { [key: string]: Json } {
  return val !== null && typeof val === 'object' && !Array.isArray(val);
}

function deepMerge(a: Json, b: Json): Json {
  if (isObject(a) && isObject(b)) {
    const result: { [key: string]: Json } = {};
    const keys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
    for (const key of keys) {
      if (key in a && key in b) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }

  if (Array.isArray(a) && Array.isArray(b)) {
    const result: Json[] = [...a];
    const seen = new Set<string>(a.map((item) => JSON.stringify(item)));
    for (const item of b) {
      const key = JSON.stringify(item);
      if (!seen.has(key)) {
        result.push(item);
        seen.add(key);
      }
    }
    return result;
  }

  return b;
}

function sortKeys(val: Json): Json {
  if (isObject(val)) {
    const sorted: { [key: string]: Json } = {};
    const keys = Object.keys(val).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(val[key]);
    }
    return sorted;
  }
  if (Array.isArray(val)) {
    return val.map((item) => sortKeys(item));
  }
  return val;
}

