public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString().trim();

        List<String[]> products = parseProducts(json);

        List<String[]> filtered = new ArrayList<>();
        for (String[] p : products) {
            double price = Double.parseDouble(p[1]);
            if (price > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort((a, b) -> a[0].compareTo(b[0]));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        double total = 0.0;
        for (String[] p : filtered) {
            double price = Double.parseDouble(p[1]);
            System.out.printf("%s: $%.2f%n", p[0], price);
            total += price;
        }
        System.out.println();
        System.out.println("Count: " + filtered.size());
        System.out.printf("Total: $%.2f%n", total);
    }

    static List<String[]> parseProducts(String json) {
        List<String[]> result = new ArrayList<>();
        if (json.startsWith("[")) json = json.substring(1);
        if (json.endsWith("]")) json = json.substring(0, json.length() - 1);

        int i = 0;
        while (i < json.length()) {
            int start = json.indexOf('{', i);
            if (start == -1) break;
            int depth = 0;
            int end = start;
            while (end < json.length()) {
                char c = json.charAt(end);
                if (c == '{') depth++;
                else if (c == '}') {
                    depth--;
                    if (depth == 0) break;
                }
                end++;
            }
            String obj = json.substring(start, end + 1);
            String name = extractString(obj, "name");
            String price = extractNumber(obj, "price");
            result.add(new String[]{name, price});
            i = end + 1;
        }
        return result;
    }

    static String extractString(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return "";
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
        while (idx < obj.length() && obj.charAt(idx) == ' ') idx++;
        if (idx < obj.length() && obj.charAt(idx) == '"') {
            idx++;
            int end = idx;
            while (end < obj.length() && obj.charAt(end) != '"') {
                if (obj.charAt(end) == '\\' && end + 1 < obj.length()) {
                    end += 2;
                } else {
                    end++;
                }
            }
            return obj.substring(idx, end);
        }
        return "";
    }

    static String extractNumber(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return "0";
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
        while (idx < obj.length() && obj.charAt(idx) == ' ') idx++;
        int start = idx;
        while (idx < obj.length() && (Character.isDigit(obj.charAt(idx)) || obj.charAt(idx) == '.' || obj.charAt(idx) == '-' || obj.charAt(idx) == '+')) {
            idx++;
        }
        return obj.substring(start, idx);
    }
}

