#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;

    size_t size = 4096;
    char *buf = malloc(size);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    size_t len = 0;
    size_t n;
    while ((n = fread(buf + len, 1, size - len - 1, fp)) > 0) {
        len += n;
        if (len + 1 >= size) {
            size *= 2;
            char *tmp = realloc(buf, size);
            if (!tmp) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = tmp;
        }
    }
    buf[len] = '\0';
    pclose(fp);

    /* strip trailing whitespace */
    while (len > 0 &&
           (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
            buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

int main(void)
{
    char *hostname = run_command("hostname");
    char *os       = run_command("uname -s");
    char *arch     = run_command("uname -m");
    char *username = run_command("whoami");

    if (!hostname) hostname = strdup("unknown");
    if (!os)       os       = strdup("unknown");
    if (!arch)     arch     = strdup("unknown");
    if (!username) username = strdup("unknown");

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    free(hostname);
    free(os);
    free(arch);
    free(username);

    return 0;
}

