interface Employee {
  employee_id: string;
  name: string;
  department: string;
  salary: number;
  start_date: string;
  rating: string;
}

const rows: Employee[] = [];
for (let i = 1; i < lines.length; i++) {
  const cols = lines[i].split(',');
  if (cols.length < 6) continue;
  rows.push({
    employee_id: cols[0].trim(),
    name: cols[1].trim(),
    department: cols[2].trim(),
    salary: parseFloat(cols[3].replace(/[^0-9.-]/g, '')),
    start_date: cols[4].trim(),
    rating: cols[5].trim()
  });
}

function formatWithCommas(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const negative = fixed.startsWith('-');
  const abs = negative ? fixed.slice(1) : fixed;
  const dotIndex = abs.indexOf('.');
  const intPart = dotIndex === -1 ? abs : abs.slice(0, dotIndex);
  const decPart = dotIndex === -1 ? '' : abs.slice(dotIndex + 1);
  const intFormatted = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  let result = intFormatted;
  if (decimals > 0) {
    result += '.' + decPart;
  }
  return (negative ? '-' : '') + result;
}

