for (const row of rows) {
  deptCounts[row.department] = (deptCounts[row.department] || 0) + 1;
}

const totalBudget: number = rows.reduce((sum, row) => sum + row.salary, 0);

const out: string[] = [];
out.push('=== Salary Report ===');
out.push('');
out.push('Average Salary by Department:');
for (const dept of depts) {
  const salaries = deptSalaries[dept];
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  out.push(`  ${dept}: $${formatWithCommas(avg, 2)}`);
}
out.push('');
out.push(`Highest Paid: ${highestPaid.name} ($${formatWithCommas(highestPaid.salary, 0)})`);
out.push('');
out.push('Departments with >2 employees:');
