#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char *name;
    char *department;
    double salary;
} Employee;

typedef struct {
    char *name;
    double sum;
    int count;
} DeptAgg;

static int compare_depts(const void *a, const void *b) {
    const DeptAgg *da = (const DeptAgg *)a;
    const DeptAgg *db = (const DeptAgg *)b;
    return strcmp(da->name, db->name);
}

static void format_commas(long long val, char *buf, size_t bufsize) {
    char num[32];
    snprintf(num, sizeof(num), "%lld", val);
    int len = (int)strlen(num);
    int pos = 0;
    for (int i = 0; i < len; i++) {
        int remaining = len - i;
        if (i > 0 && remaining > 1 && remaining % 3 == 0) {
            buf[pos++] = ',';
        }
        buf[pos++] = num[i];
    }
    buf[pos] = '\0';
}

static void format_money_2dp(double val, char *buf, size_t bufsize) {
    long long v = (long long)(val * 100.0 + 0.5);
    long long intpart = v / 100;
    long long fracpart = v % 100;
    if (fracpart < 0) fracpart = -fracpart;
    char num[32];
    snprintf(num, sizeof(num), "%lld", intpart);
    int len = (int)strlen(num);
    int pos = 0;
    for (int i = 0; i < len; i++) {
        int remaining = len - i;
        if (i > 0 && remaining > 1 && remaining % 3 == 0) {
            buf[pos++] = ',';
        }
        buf[pos++] = num[i];
    }
    snprintf(buf + pos, bufsize - pos, ".%02lld", fracpart);
}

static void format_money_0dp(double val, char *buf, size_t bufsize) {
    long long v = (long long)(val + 0.5);
    format_commas(v, buf, bufsize);
}

