        char *p = line;
        while (1) {
            fields[nf++] = p;
            char *comma = strchr(p, ',');
            if (!comma) break;
            *comma = '\0';
            p = comma + 1;
        }
        if (nf < 6) continue;

        if (n >= (int)cap) {
            cap *= 2;
            emps = (Employee *)realloc(emps, cap * sizeof(Employee));
