        for (int j = 0; j < nd; j++) {
            if (strcmp(depts[j].name, emps[i].department) == 0) {
                found = j;
                break;
            }
        }
        if (found < 0) {
            if (nd >= dcap) {
                dcap *= 2;
                depts = (DeptAgg *)realloc(depts, dcap * sizeof(DeptAgg));
            }
            depts[nd].name = dupstr(emps[i].department);
            depts[nd].sum = 0.0;
            depts[nd].count = 0;
            found = nd++;
        }
        depts[found].sum += emps[i].salary;
        depts[found].count++;
    }

    qsort(depts, nd, sizeof(DeptAgg), compare_depts);

    /* Find highest paid */
    int maxidx = 0;
    for (int i = 1; i < n; i++) {
        if (emps[i].salary > emps[maxidx].salary)
            maxidx = i;
    }

    /* Total budget */
    double total = 0.0;
    for (int i = 0; i < n; i++)
        total += emps[i].salary;

    /* Print output */
    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < nd; i++) {
        double avg = depts[i].sum / depts[i].count;
        char buf[64];
        format_money_2dp(avg, buf, sizeof(buf));
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");
    {
        char buf[64];
        format_money_0dp(emps[maxidx].salary, buf, sizeof(buf));
        printf("Highest Paid: %s ($%s)\n", emps[maxidx].name, buf);
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < nd; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    {
        char buf[64];
        format_money_0dp(total, buf, sizeof(buf));
        printf("Total Budget: $%s\n", buf);
    }

    /* Cleanup */
    for (int i = 0; i < n; i++) {
        free(emps[i].name);
        free(emps[i].department);
    }
    free(emps);
    for (int i = 0; i < nd; i++)
        free(depts[i].name);
    free(depts);

    return 0;
}

