use std::collections::HashMap;
use std::io::{Read, Write};
use std::net::TcpStream;

enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(HashMap<String, Value>),
}

struct JsonParser {
    input: Vec<char>,
    pos: usize,
}

impl JsonParser {
    fn new(s: &str) -> Self {
        JsonParser {
            input: s.chars().collect(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Value {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Value::String(self.parse_string()),
            Some('t') => {
                self.pos += 4;
                Value::Bool(true)
            }
            Some('f') => {
                self.pos += 5;
                Value::Bool(false)
            }
            Some('n') => {
                self.pos += 4;
                Value::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.next(); // consume opening "
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\x08'),
                    Some('f') => s.push('\x0c'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            if let Some(c) = self.next() {
                                code = code * 16 + c.to_digit(16).unwrap_or(0);
                            }
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => {}
                },
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> Value {
        let mut s = String::new();
        if self.peek() == Some('-') {
            s.push('-');
            self.pos += 1;
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.peek() == Some('.') {
            s.push('.');
            self.pos += 1;
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
        if self.peek() == Some('e') || self.peek() == Some('E') {
            s.push(self.peek().unwrap());
            self.pos += 1;
            if self.peek() == Some('+') || self.peek() == Some('-') {
                s.push(self.peek().unwrap());
                self.pos += 1;
            }
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
        let f = s.parse::<f64>().unwrap_or(0.0);
        Value::Number(f)
    }

    fn parse_object(&mut self) -> Value {
        self.next(); // consume {
        let mut map = HashMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Value::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next(); // consume :
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Value::Object(map)
    }

    fn parse_array(&mut self) -> Value {
        self.next(); // consume [
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Value::Array(arr);
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => break,
            }
        }
        Value::Array(arr)
    }
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");

    let request =
        "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream
        .write_all(request.as_bytes())
        .expect("Failed to write request");

    let mut response = String::new();
    let mut buf = [0u8; 4096];
    loop {
        let n = stream.read(&mut buf).expect("Failed to read response");
        if n == 0 {
            break;
        }
        response.push_str(&String::from_utf8_lossy(&buf[..n]));
    }

    // Extract body after HTTP headers
    let body = if let Some(idx) = response.find("\r\n\r\n") {
        &response[idx + 4..]
    } else if let Some(idx) = response.find("\n\n") {
        &response[idx + 2..]
    } else {
        ""
    };

    let mut parser = JsonParser::new(body);
    let value = parser.parse_value();

    let products = match value {
        Value::Array(arr) => arr,
        _ => Vec::new(),
    };

    let mut filtered: Vec<(String, f64)> = Vec::new();
    for item in &products {
        if let Value::Object(map) = item {
            let name = match map.get("name") {
                Some(Value::String(s)) => s.clone(),
                _ => String::new(),
            };
            let price = match map.get("price") {
                Some(Value::Number(n)) => *n,
                _ => 0.0,
            };
            if price > 50.00 {
                filtered.push((name, price));
            }
        }
    }

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
