import Foundation

let A = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
let B = [[9, 8, 7], [6, 5, 4], [3, 2, 1]]

func multiply(_ M1: [[Int]], _ M2: [[Int]]) -> [[Int]] {
    let rows = M1.count
    let cols = M2[0].count
    let inner = M1[0].count
    var result = [[Int]](repeating: [Int](repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            var sum = 0
            for k in 0..<inner {
                sum += M1[i][k] * M2[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

func determinant(_ M: [[Int]]) -> Int {
    let n = M.count
    if n == 1 { return M[0][0] }
    if n == 2 { return M[0][0] * M[1][1] - M[0][1] * M[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n where k != j {
                row.append(M[i][k])
            }
            minor.append(row)
        }
        det += (j % 2 == 0 ? 1 : -1) * M[0][j] * determinant(minor)
    }
    return det
}

func printMatrix(_ M: [[Int]]) {
    for row in M {
        var line = "  "
        for (i, v) in row.enumerated() {
            if i > 0 { line += " " }
            line += String(format: "%4d", v)
        }
        print(line)
    }
}

