import * as fs from 'fs';
import * as path from 'path';

const ROOT = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_3u8jixpn/project_tree';

interface FileStats {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(buffer: Buffer): number {
  if (buffer.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < buffer.length; i++) {
    if (buffer[i] === 10) count++;
  }
  if (buffer[buffer.length - 1] !== 10) count++;
  return count;
}

function walkDir(dir: string, root: string, results: Map<string, FileStats[]>): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(root, fullPath).split(path.sep).join('/');

    if (entry.isDirectory()) {
      walkDir(fullPath, root, results);
    } else if (entry.isFile()) {
      const buffer = fs.readFileSync(fullPath);
      const lines = countLines(buffer);
      const chars = buffer.length;
      const ext = path.extname(entry.name);

      if (!results.has(ext)) {
        results.set(ext, []);
      }
      results.get(ext)!.push({ relativePath, lines, chars });
    }
  }
}

const results = new Map<string, FileStats[]>();
walkDir(ROOT, ROOT, results);

const extensions = Array.from(results.keys()).sort();

for (const ext of extensions) {
  results.get(ext)!.sort((a, b) =>
    a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0
  );
}

let output = '=== File Tree Analysis ===\n\n';

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of extensions) {
  const files = results.get(ext)!;
  const filesCount = files.length;
  const linesSum = files.reduce((s, f) => s + f.lines, 0);
  const charsSum = files.reduce((s, f) => s + f.chars, 0);

  output += `Extension: ${ext}\n`;
  output += `  Files: ${filesCount}\n`;
  output += `  Total Lines: ${linesSum}\n`;
  output += `  Total Characters: ${charsSum}\n`;

  for (const file of files) {
    output += `    ${file.relativePath}: ${file.lines} lines, ${file.chars} chars\n`;
  }

  totalFiles += filesCount;
  totalLines += linesSum;
  totalChars += charsSum;
}

output += '\n';
output += `Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

process.stdout.write(output);

