import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    static class FileInfo {
        String relPath;
        long lines;
        long chars;
        FileInfo(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    static long countLines(byte[] bytes) {
        if (bytes.length == 0) return 0;
        long newlines = 0;
        for (byte b : bytes) {
            if (b == '\n') newlines++;
        }
        if (bytes[bytes.length - 1] != '\n') newlines++;
        return newlines;
    }

    static String getExtension(String fileName) {
        int lastDot = fileName.lastIndexOf('.');
        if (lastDot <= 0) return "(none)";
        return fileName.substring(lastDot);
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_3u8jixpn/project_tree");

        Map<String, List<FileInfo>> byExt = new TreeMap<>();
        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                if (Files.isSymbolicLink(file)) {
                    return FileVisitResult.CONTINUE;
                }
                if (!Files.isRegularFile(file)) {
                    return FileVisitResult.CONTINUE;
                }

                Path relPath = root.relativize(file);
                String relPathStr = relPath.toString().replace(File.separatorChar, '/');

                byte[] bytes = Files.readAllBytes(file);
                long charCount = bytes.length;
                long lineCount = countLines(bytes);

                String fileName = file.getFileName().toString();
                String ext = getExtension(fileName);

                byExt.computeIfAbsent(ext, k -> new ArrayList<>())
                      .add(new FileInfo(relPathStr, lineCount, charCount));

                totalFiles++;
                totalLines += lineCount;
                totalChars += charCount;

                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                if (Files.isSymbolicLink(dir)) {
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return FileVisitResult.CONTINUE;
            }
        });

        for (List<FileInfo> list : byExt.values()) {
            list.sort(Comparator.comparing(f -> f.relPath));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        for (Map.Entry<String, List<FileInfo>> entry : byExt.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> files = entry.getValue();

            long extLines = 0;
            long extChars = 0;
            for (FileInfo f : files) {
                extLines += f.lines;
                extChars += f.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");
            for (FileInfo f : files) {
                sb.append("    ").append(f.relPath).append(": ")
                  .append(f.lines).append(" lines, ")
                  .append(f.chars).append(" chars\n");
            }
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ")
          .append(totalLines).append(" lines, ")
          .append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }
}

