use std::collections::{BTreeMap, HashSet};
use std::fs;
use std::io::Read;
use std::path::Path;

fn count_lines_and_chars(path: &Path) -> (usize, usize) {
    let mut buf = Vec::new();
    if let Ok(mut f) = fs::File::open(path) {
        let _ = f.read_to_end(&mut buf);
    }
    let chars = buf.len();
    let lines = if buf.is_empty() {
        0
    } else {
        let newline_count = buf.iter().filter(|&&b| b == b'\n').count();
        if buf.last() == Some(&b'\n') {
            newline_count
        } else {
            newline_count + 1
        }
    };
    (lines, chars)
}

fn get_extension(path: &Path) -> String {
    match path.extension() {
        Some(ext) => format!(".{}", ext),
        None => "(no ext)".to_string(),
    }
}

fn walk(
    dir: &Path,
    base: &Path,
    visited: &mut HashSet<u64>,
    result: &mut BTreeMap<String, Vec<(String, usize, usize)>>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            if let Ok(metadata) = fs::metadata(&path) {
                let inode = metadata.ino();
                if !visited.insert(inode) {
                    continue;
                }
            }
            walk(&path, base, visited, result);
        } else if path.is_file() {
            let (lines, chars) = count_lines_and_chars(&path);
            let rel_path = path
                .strip_prefix(base)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/");
            let ext = get_extension(&path);
            result.entry(ext).or_default().push((rel_path, lines, chars));
        }
    }
}

fn main() {
    let base = Path::new(
        "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_3u8jixpn/project_tree",
    );

    let mut visited: HashSet<u64> = HashSet::new();
    let mut result: BTreeMap<String, Vec<(String, usize, usize)>> = BTreeMap::new();

    if let Ok(metadata) = fs::metadata(base) {
        let _ = visited.insert(metadata.ino());
    }

    walk(base, base, &mut visited, &mut result);

    for files in result.values_mut() {
        files.sort_by(|a, b| a.0.cmp(&b.0));
    }

    let total_files: usize = result.values().map(|v| v.len()).sum();
    let total_lines: usize = result
        .values()
        .map(|v| v.iter().map(|(_, l, _)| l).sum::<usize>())
        .sum();
    let total_chars: usize = result
        .values()
        .map(|v| v.iter().map(|(_, _, c)| c).sum::<usize>())
        .sum();

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, files) in &result {
        println!("Extension: {}", ext);
        println!("  Files: {}", files.len());
        let lines: usize = files.iter().map(|(_, l, _)| l).sum();
