public class Main {
    static String json;
    static int pos;

    static void skipWs() {
        while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
    }

    static String parseString() {
        skipWs();
        if (pos >= json.length() || json.charAt(pos) != '"') throw new RuntimeException("Expected string at " + pos);
        pos++;
        StringBuilder sb = new StringBuilder();
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == '\\') {
                pos++;
                char e = json.charAt(pos);
                if (e == 'u') {
                    sb.append((char) Integer.parseInt(json.substring(pos + 1, pos + 5), 16));
                    pos += 4;
                } else {
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'n': sb.append('\n'); break;
                        case 't': sb.append('\t'); break;
                        case 'r': sb.append('\r'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        default: sb.append(e);
                    }
                }
                pos++;
            } else if (c == '"') {
                pos++;
                break;
            } else {
                sb.append(c);
                pos++;
            }
        }
        return sb.toString();
    }

    static double parseNumber() {
        skipWs();
        int start = pos;
        if (pos < json.length() && json.charAt(pos) == '-') pos++;
        while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
        if (pos < json.length() && json.charAt(pos) == '.') {
            pos++;
            while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
        }
