            pos++;
            skipWs();
            if (pos < json.length() && json.charAt(pos) == '}') { pos++; return; }
            while (pos < json.length() && json.charAt(pos) != '}') {
                parseString();
                skipWs();
                if (pos < json.length() && json.charAt(pos) == ':') pos++;
                skipValue();
                skipWs();
                if (pos < json.length() && json.charAt(pos) == ',') pos++;
                skipWs();
