            String from = edgeFrom.get(i);
            String to = edgeTo.get(i);
            double w = edgeWeight.get(i);
            adj.computeIfAbsent(from, k -> new ArrayList<>()).add(new String[]{to, String.valueOf(w)});
            adj.computeIfAbsent(to, k -> new ArrayList<>()).add(new String[]{from, String.valueOf(w)});
        }

        // Dijkstra's algorithm
        Map<String, Double> dist = new HashMap<>();
        PriorityQueue<Object[]> pq = new PriorityQueue<>((a, b) -> Double.compare((Double) a[0], (Double) b[0]));

        for (String n : nodes) dist.put(n, Double.POSITIVE_INFINITY);
        dist.put("A", 0.0);
        pq.add(new Object[]{0.0, "A"});

        while (!pq.isEmpty()) {
            Object[] curr = pq.poll();
            double d = (Double) curr[0];
            String u = (String) curr[1];

            if (d > dist.get(u)) continue;

            for (String[] edge : adj.getOrDefault(u, Collections.emptyList())) {
                String v = edge[0];
                double w = Double.parseDouble(edge[1]);
                double nd = d + w;
                if (nd < dist.get(v)) {
                    dist.put(v, nd);
                    pq.add(new Object[]{nd, v});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();

        List<String> sortedNodes = new ArrayList<>(nodes);
        Collections.sort(sortedNodes);

        for (String n : sortedNodes) {
            double d = dist.get(n);
            if (d == Double.POSITIVE_INFINITY) {
                System.out.println("A -> " + n + ": unreachable");
            } else if (d == Math.floor(d) && Math.abs(d) < 1e15) {
                System.out.println("A -> " + n + ": " + (long) d);
            } else {
                System.out.println("A -> " + n + ": " + d);
            }
        }
    }
}

