                        for item in arr {
                            if let Json::Object(e) = item {
                                let mut from = String::new();
                                let mut to = String::new();
                                let mut weight = 0.0f64;
                                for (ek, ev) in e {
                                    if ek == "from" {
                                        if let Json::String(s) = ev { from = s.clone(); }
                                    } else if ek == "to" {
                                        if let Json::String(s) = ev { to = s.clone(); }
                                    } else if ek == "weight" {
                                        if let Json::Number(n) = ev { weight = *n; }
                                    }
                                }
                                edges.push((from, to, weight));
                            }
                        }
                    }
                }
            }
            (nodes, edges)
        }
        _ => panic!("Invalid JSON structure"),
    };

    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for n in &nodes {
