    heap.push((0.0, source.clone()));

    while let Some((d, node)) = heap.pop() {
        if d > dist.get(&node).copied().unwrap_or(f64::INFINITY) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (nb, w) in neighbors {
                let nd = d + w;
                let cur = dist.get(nb).copied().unwrap_or(f64::INFINITY);
                if nd < cur {
                    dist.insert(nb.clone(), nd);
                    heap.push((nd, nb.clone()));
                }
            }
        }
    }

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

