                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_value(v->items[i], indent + 1);
                if (i < v->array_len - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputc(']', stdout);
            break;
        case J_OBJECT:
            if (v->obj_len == 0) {
                fputs("{}", stdout);
                break;
            }
            fputs("{\n", stdout);
            for (int i = 0; i < v->obj_len; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_string_escaped(v->pairs[i].key);
                fputs(": ", stdout);
                print_value(v->pairs[i].value, indent + 1);
                if (i < v->obj_len - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputc('}', stdout);
            break;
    }
}

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return NULL; }
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    fclose(f);
    buf[rd] = '\0';
    *out_len = (int)rd;
    return buf;
}

